<?php
require 'config/auth.php';require 'config/db.php';
if(!has_permission('control.view')&&!has_permission('control.manage'))require_permission('control.view');
$year=(int)($_GET['year']??fiscal_year_for_date());
$unitId=is_admin()?(int)($_GET['unit_id']??0):current_unit_id();
$q=trim($_GET['q']??'');$error='';
$units=is_admin()?$conn->query('SELECT id,unit_code,unit_name FROM units ORDER BY unit_code')->fetch_all(MYSQLI_ASSOC):[];
$sql="SELECT ca.*,u.unit_code,bt.doc_no,bt.doc_date,bt.gfmis_date,
COALESCE(SUM(CASE WHEN e.entry_type='increase' THEN e.amount ELSE 0 END),0) extra,
COALESCE(SUM(CASE WHEN e.entry_type='payment' THEN e.amount ELSE 0 END),0) paid,
COALESCE(SUM(CASE WHEN e.entry_type IN ('transfer_out','return_army','remittance') THEN e.amount ELSE 0 END),0) outgoing,
COUNT(e.id) entry_count
FROM control_accounts ca JOIN units u ON u.id=ca.unit_id LEFT JOIN budget_transfers bt ON bt.id=ca.source_transfer_id LEFT JOIN active_control_entries e ON e.control_account_id=ca.id
WHERE ca.cancelled_at IS NULL AND ca.fiscal_year=?";
$types='i';$params=[$year];if($unitId>0){$sql.=' AND ca.unit_id=?';$types.='i';$params[]=$unitId;}
if($q!==''){$sql.=' AND (ca.budget_code LIKE ? OR ca.item_name LIKE ? OR ca.gfmis_code LIKE ? OR ca.activity_code LIKE ?)';$types.='ssss';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}
$sql.=' GROUP BY ca.id ORDER BY COALESCE(bt.gfmis_date,bt.doc_date,DATE(ca.created_at)) DESC,ca.created_at DESC';
$stmt=$conn->prepare($sql);$stmt->bind_param($types,...$params);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
function installment_label(string $v):string{return $v==='additional'?'งวดเพิ่มเติม':'งวดที่ '.$v;}
?>
<!doctype html><html lang="th"><head><meta name="viewport" content="width=device-width, initial-scale=1"><meta charset="utf-8"><title>บัญชีคุม GFMIS</title><link rel="stylesheet" href="assets/css/style.css?v=<?=filemtime(__DIR__.'/assets/css/style.css')?>"></head><body><?php require 'template/nav.php';?><main class="container"><section class="panel"><h1 class="page-title">บัญชีคุม GFMIS</h1><p class="page-subtitle">ยอดเงินคำนวณจากเอกสารรับงบและรายการเคลื่อนไหวของแต่ละบัญชีคุมงบประมาณ</p><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(isset($_GET['deleted'])):?><div class="alert alert-success">ลบบัญชีคุมแล้ว</div><?php endif;?><form method="get" class="toolbar"><label>ปีงบประมาณ</label><input type="number" name="year" value="<?=$year?>" style="width:150px"><?php if(is_admin()):?><label>หน่วย</label><select name="unit_id" style="width:300px"><option value="0">ทุกหน่วย</option><?php foreach($units as $u):?><option value="<?=(int)$u['id']?>" <?=$unitId===(int)$u['id']?'selected':''?>><?=htmlspecialchars($u['unit_code'].' '.$u['unit_name'])?></option><?php endforeach;?></select><?php endif;?><input name="q" value="<?=htmlspecialchars($q)?>" placeholder="ค้นหา รหัสงบประมาณ / รายการ / GFMIS" style="max-width:330px"><button class="btn btn-primary">ค้นหา</button><a class="btn btn-success" href="add_budget.php">เพิ่มงบโอนครั้งแรก</a></form></section>
<section class="panel"><div class="table-wrap"><table><tr><th>หน่วย / รหัสงบประมาณ</th><th>รายการ</th><th>รหัส GFMIS</th><th>รหัสกิจกรรม</th><th>งวด</th><th class="text-right">รับรวม</th><th class="text-right">ตัดจ่าย</th><th class="text-right">คงเหลือ</th><th>จัดการ</th></tr><?php foreach($rows as $r):$received=(float)$r['received_amount']+(float)$r['extra'];$balance=$received-(float)$r['paid']-(float)$r['outgoing'];?><tr><td><?=htmlspecialchars($r['unit_code'])?><div><strong><?=htmlspecialchars($r['budget_code'])?></strong></div></td><td><?=htmlspecialchars($r['item_name'])?><div class="muted"><?=htmlspecialchars((string)$r['doc_no'])?></div></td><td><?=htmlspecialchars((string)$r['gfmis_code'])?></td><td><?=htmlspecialchars((string)$r['activity_code'])?></td><td><?=htmlspecialchars(installment_label((string)$r['installment_no']))?></td><td class="text-right"><?=number_format($received,2)?></td><td class="text-right"><?=number_format((float)$r['paid'],2)?></td><td class="text-right"><b><?=number_format($balance,2)?></b></td><td><div class="action-links"><a href="control_account_detail.php?id=<?=(int)$r['id']?>">รายละเอียด</a><a href="transactions.php?year=<?=$year?>&unit_id=<?=$unitId?>&account_id=<?=(int)$r['id']?>">ตัดจ่าย</a><?php if($r['source_transfer_id']):?><a href="edit_budget.php?id=<?=(int)$r['source_transfer_id']?>">แก้ไข</a><?php if(has_permission('budget.delete')):?><a href="delete_budget.php?id=<?=(int)$r['source_transfer_id']?>">ลบ</a><?php endif;?><?php elseif(has_permission('control.manage')&&(int)$r['entry_count']===0):?><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="9" class="text-center">ไม่มีบัญชีคุมในปีที่เลือก</td></tr><?php endif;?></table></div></section></main></body></html>
